import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BXzK3EA4.js";const i="/assets/image-domainEN2025112504.qXy5Oule.png",n="/assets/image-domainEN2025112503.Djim0C5a.png",s="/assets/image-domainZN2025112502.TPYOXvS7.png",b=JSON.parse('{"title":"DNS Management","description":"","frontmatter":{"title":"DNS Management"},"headers":[],"relativePath":"operations-knowledge-base/domain/dns-management.md","filePath":"operations-knowledge-base/domain/dns-management.md","lastUpdated":1794292919000}'),d={name:"operations-knowledge-base/domain/dns-management.md"};function c(h,a,l,p,m,u){return r(),o("div",null,[...a[0]||(a[0]=[t('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>After a domain has been activated, you need to configure DNS settings in the platform backend. This allows the domain to be linked to the target server or service, so users can access the corresponding website, application, or other content through the domain name.</p><h2 id="_1-dns-configuration-process" tabindex="-1">1. DNS Configuration Process <a class="header-anchor" href="#_1-dns-configuration-process" aria-label="Permalink to &quot;1. DNS Configuration Process&quot;">​</a></h2><p>There are two DNS configuration methods. You should choose the appropriate one depending on your domain setup to ensure the records take effect correctly.</p><h3 id="access-path" tabindex="-1">Access Path <a class="header-anchor" href="#access-path" aria-label="Permalink to &quot;Access Path&quot;">​</a></h3><p>Go to: Product Management → Domains &amp; Websites → Domains</p><p>View your domain list</p><p>Click “Details” on the right to enter the management panel</p><hr><h3 id="method-1" tabindex="-1">Method 1 <a class="header-anchor" href="#method-1" aria-label="Permalink to &quot;Method 1&quot;">​</a></h3><h4 id="verification-notes" tabindex="-1">Verification Notes <a class="header-anchor" href="#verification-notes" aria-label="Permalink to &quot;Verification Notes&quot;">​</a></h4><p>After the domain is activated, verification is required.</p><p>Please check your email inbox after placing the order, including the spam folder, and complete the verification promptly to ensure normal use of the domain.</p><h4 id="root-domain-primary-domain" tabindex="-1">Root Domain (Primary Domain) <a class="header-anchor" href="#root-domain-primary-domain" aria-label="Permalink to &quot;Root Domain (Primary Domain)&quot;">​</a></h4><p>Leave Hostname empty (or use @ if saving fails)</p><p>Enter the target IP address (e.g., 192.168.1.1)</p><p>This maps: Example Domain → IP</p><p>If saving fails when the hostname is left blank, enter @ as the hostname and save again.</p><h4 id="subdomain" tabindex="-1">Subdomain <a class="header-anchor" href="#subdomain" aria-label="Permalink to &quot;Subdomain&quot;">​</a></h4><p>Enter hostname prefix (e.g., www)</p><p>Enter target IP</p><p>This maps: www.example.com → IP</p><p><img src="'+i+'" alt=""></p><h4 id="nameservers" tabindex="-1">Nameservers <a class="header-anchor" href="#nameservers" aria-label="Permalink to &quot;Nameservers&quot;">​</a></h4><p>Use the default nameservers</p><p><strong><img src="'+n+'" alt=""></strong></p><hr><h3 id="method-2" tabindex="-1">Method 2 <a class="header-anchor" href="#method-2" aria-label="Permalink to &quot;Method 2&quot;">​</a></h3><h4 id="root-domain" tabindex="-1">Root Domain <a class="header-anchor" href="#root-domain" aria-label="Permalink to &quot;Root Domain&quot;">​</a></h4><p>Record type: A</p><p>Enter target IP (e.g., 192.168.1.1)</p><h4 id="subdomain-1" tabindex="-1">Subdomain <a class="header-anchor" href="#subdomain-1" aria-label="Permalink to &quot;Subdomain&quot;">​</a></h4><p>Hostname: prefix (e.g., www)</p><p>Record type: A</p><p>Enter target IP</p><p><img src="'+s+'" alt=""></p><h4 id="save-configuration" tabindex="-1">Save Configuration <a class="header-anchor" href="#save-configuration" aria-label="Permalink to &quot;Save Configuration&quot;">​</a></h4><p>Click “Save” after completing setup.</p><p>DNS propagation may take 24–72 hours to fully take effect.</p><hr><h2 id="_2-dns-record-types" tabindex="-1">2. DNS Record Types <a class="header-anchor" href="#_2-dns-record-types" aria-label="Permalink to &quot;2. DNS Record Types&quot;">​</a></h2><h3 id="a-record" tabindex="-1">A Record <a class="header-anchor" href="#a-record" aria-label="Permalink to &quot;A Record&quot;">​</a></h3><p>Maps a domain to an IPv4 address. Example: Example Domain → 192.168.1.10</p><h3 id="aaaa-record" tabindex="-1">AAAA Record <a class="header-anchor" href="#aaaa-record" aria-label="Permalink to &quot;AAAA Record&quot;">​</a></h3><p>Maps a domain to an IPv6 address. Example: Example Domain → 2001:db8::1</p><h3 id="cname-record" tabindex="-1">CNAME Record <a class="header-anchor" href="#cname-record" aria-label="Permalink to &quot;CNAME Record&quot;">​</a></h3><p>Maps a domain alias to another domain. Example: www.example.com → Example Domain</p><p>Note: A CNAME record cannot coexist with an A record for the same hostname.</p><h3 id="forward" tabindex="-1">Forward <a class="header-anchor" href="#forward" aria-label="Permalink to &quot;Forward&quot;">​</a></h3><p>Forwards requests for a domain to another URL.</p><p>The browser address bar will display the redirected URL.</p><p>Example: old-site.com → <a href="https://new-site.com/page" target="_blank" rel="noreferrer">https://new-site.com/page</a></p><h3 id="stealth-forward" tabindex="-1">Stealth Forward <a class="header-anchor" href="#stealth-forward" aria-label="Permalink to &quot;Stealth Forward&quot;">​</a></h3><p>Keeps the original domain visible while loading content from another site, similar to an iframe.</p><h3 id="txt-record" tabindex="-1">TXT Record <a class="header-anchor" href="#txt-record" aria-label="Permalink to &quot;TXT Record&quot;">​</a></h3><p>Stores text data for verification or configuration.</p><p>Common uses:</p><p>Domain ownership verification</p><p>Email authentication (SPF, DKIM)</p><p>Example: v=spf1 include:_spf.google.com ~all</p><h3 id="mx-record" tabindex="-1">MX Record <a class="header-anchor" href="#mx-record" aria-label="Permalink to &quot;MX Record&quot;">​</a></h3><p>Defines mail servers for receiving emails. Example: Example Domain → mail.example.com</p><h3 id="mxe-record" tabindex="-1">MXE Record <a class="header-anchor" href="#mxe-record" aria-label="Permalink to &quot;MXE Record&quot;">​</a></h3><p>Allows email to be delivered directly to a server IP without complex configuration.</p><p>It automatically creates a special MX record.</p><h3 id="spf-record" tabindex="-1">SPF Record <a class="header-anchor" href="#spf-record" aria-label="Permalink to &quot;SPF Record&quot;">​</a></h3><p>SPF is an anti-spam mechanism and is a type of TXT record.</p><p>It specifies which servers are allowed to send emails for your domain.</p><h3 id="url-redirect" tabindex="-1">URL Redirect <a class="header-anchor" href="#url-redirect" aria-label="Permalink to &quot;URL Redirect&quot;">​</a></h3><p>Redirects a domain using HTTP 301/302.</p><h3 id="url-frame" tabindex="-1">URL Frame <a class="header-anchor" href="#url-frame" aria-label="Permalink to &quot;URL Frame&quot;">​</a></h3><p>Embeds another website inside your domain using a frame-based display.</p><hr><h2 id="_3-important-notes" tabindex="-1">3. Important Notes <a class="header-anchor" href="#_3-important-notes" aria-label="Permalink to &quot;3. Important Notes&quot;">​</a></h2><h3 id="accuracy-of-records" tabindex="-1">Accuracy of Records <a class="header-anchor" href="#accuracy-of-records" aria-label="Permalink to &quot;Accuracy of Records&quot;">​</a></h3><p>Ensure hostname and IP values are correct.</p><p>Misconfiguration may cause:</p><p>Domain not resolving</p><p>Website inaccessible</p><h3 id="propagation-time" tabindex="-1">Propagation Time <a class="header-anchor" href="#propagation-time" aria-label="Permalink to &quot;Propagation Time&quot;">​</a></h3><p>DNS changes require global synchronization.</p><p>This may take 24–72 hours.</p><p>Temporary inconsistency is normal.</p><p>You can verify using:</p><p>nslookup Example Domain</p><p>ping Example Domain</p><h3 id="nameserver-changes" tabindex="-1">Nameserver Changes <a class="header-anchor" href="#nameserver-changes" aria-label="Permalink to &quot;Nameserver Changes&quot;">​</a></h3><p>Old DNS records will gradually become invalid.</p><p>Ensure new nameservers have the correct records configured.</p><p>Prevent service interruption.</p><h3 id="domain-verification" tabindex="-1">Domain Verification <a class="header-anchor" href="#domain-verification" aria-label="Permalink to &quot;Domain Verification&quot;">​</a></h3><p>Complete verification promptly.</p><p>Unverified domains may have DNS resolution suspended, which may affect accessibility.</p>',93)])])}const g=e(d,[["render",c]]);export{b as __pageData,g as default};
